head.script:
// WAEA-912 : UDC 내부 화면.
// wframe(iframe) 과 달리 메인 문서 안에 그대로 렌더되므로 내부 탐색 경로가 다르다.
// 탭 대상은 udcFirst → udcTextarea → udcLast 세 개뿐이어야 한다.
// UDC 는 컴포넌트 스코프라 window[id] 로 잡히지 않는다. 식별자를 직접 쓴다.
scwin.paint = function(comp, text) {
    if (comp && typeof comp.setValue === "function") { comp.setValue(text); }
};

scwin.onpageload = function() {
    window.WAEA_912_UDC_READY = true;
    scwin.paint(udcReadOnlyFirst, "skip · readOnly");
    scwin.paint(udcFirst,         "1번째 · udcFirst");
    scwin.paint(udcTextarea,      "2번째 · udcTextarea");
    scwin.paint(udcLast,          "3번째 · udcLast");
    scwin.paint(udcReadOnlyLast,  "skip · readOnly");
};
